def find_factors(number: int) -> list:
    """ Find and returns the sorted list of factors of the number.
    >>> find_factors(4)
    [1, 2, 4]
    >>> find_factors(100)
    [1, 2, 4, 5, 10, 20, 25, 50, 100]
    """
    factors = []
    for n in range(2, number):
        if number % n == 0:
            factors.append(n)
    return sorted(factors)

def is_factor(factors: list, number: int) -> bool:
    """ Checks whether a number is a factor for all factors of another number.
    >>> is_factor([1, 2, 4], 8)
    True
    >>> is_factor([1, 2, 3, 4], 8)
    False
    """
    return len(factors) == len(set([number // i for i in factors]))

