def compute_discount(price: float, percent: float) -> float:
    """Given the total price and the corresponding percent of discount,
    compute the final price.
    >>> compute_discount(10, 10)
    9
    """
    return price * (1 - percent / 100)

def compute_quantity_discount(price: float, bulk: int, discount: float) -> float:
    """Given the price, quantity and the corresponding discount percentage,
    compute the final price after the bulk discount.
    >>> compute_quantity_discount(10, 2, 5)
    8.75
    """
    if bulk >= 10:
        return price * (1 - discount / 100)
    return price

