def parse_nested_parens_parens(parens: List[str]) -> int:
    ans = 0
    for paren in parens:
        level = 0
        for char in paren:
            if char == '(':
                level += 1
            elif char == ')':
                level -= 1
        ans = max(ans, level)
    return ans


